-- Fact tables with time dimension
CREATE TABLE events (
    ts timestamptz NOT NULL,
    machine_id text,
    reason_code text,
    duration_s double precision,
    energy_kwh double precision
);

CREATE TABLE samples (
    ts timestamptz NOT NULL,
    machine_id text,
    tag text,
    value double precision
);

-- Indexes for performance
CREATE INDEX idx_events_machine_time ON events (machine_id, ts);
CREATE INDEX idx_samples_machine_time ON samples (machine_id, ts);

-- Views to expose typed data over raw_ingest
CREATE VIEW view_events AS SELECT T1.ts, T1.machine_id, T1.reason_code, T1.duration_s, T1.energy_kwh FROM raw_ingest AS T1 INNER JOIN tag_map AS T2 ON T1.source = T2.tag_id INNER JOIN machines AS T3 ON T2.machine_id = T3.id WHERE T1.payload->>'type' = 'event';

CREATE VIEW view_samples AS SELECT T1.ts, T1.machine_id, T1.tag, T1.value FROM raw_ingest AS T1 INNER JOIN tag_map AS T2 ON T1.source = T2.tag_id INNER JOIN machines AS T3 ON T2.machine_id = T3.id WHERE T1.payload->>'type' = 'sample';
